library ieee;
use ieee.std_logic_1164.all;
use ieee.std_logic_textio.all;

use std.textio.all;
use std.env.all;

entity harness is
end entity harness;

architecture sim of harness is
    signal a_sig, b_sig, sum_sig : std_logic_vector(3 downto 0);
    signal cin_sig, cout_sig     : std_logic;
begin
    dut : entity work.solution
        port map (
            a    => a_sig,
            b    => b_sig,
            cin  => cin_sig,
            sum  => sum_sig,
            cout => cout_sig
        );

    process
        variable in_line   : line;
        variable out_line  : line;
        variable a_in, b_in : std_logic_vector(3 downto 0);
        variable cin_in    : std_logic;
    begin
        readline(input, in_line);
        read(in_line, a_in);
        read(in_line, b_in);
        read(in_line, cin_in);
        a_sig   <= a_in;
        b_sig   <= b_in;
        cin_sig <= cin_in;
        wait for 1 ns;
        write(out_line, sum_sig);
        write(out_line, cout_sig);
        writeline(output, out_line);
        finish;
    end process;
end architecture sim;

generator.source:
"""Random operand pairs for the VHDL Ripple-Carry Adder testbench.

Only the input is produced here -- the expected output is captured by
running the reference solution's own simulation, so the two can never
disagree. Weighted towards values likely to overflow, since a solution
that only gets cout right by leaving it tied to \'0\' passes every case
that does not overflow.
"""

WIDTH = 4


def _bits(value):
    return "".join(str((value >> b) & 1) for b in range(WIDTH - 1, -1, -1))


def _case(name, a, b, cin, description=""):
    stdin = "%s %s %d\n" % (_bits(a), _bits(b), cin)
    return {"name": name, "stdin": stdin, "description": description}


def generate(rng, count):
    builders = (_likely_overflow, _random, _likely_overflow, _random)
    return [builders[i % len(builders)](rng, i + 1) for i in range(count)]


def _random(rng, index):
    return _case("random #%d" % index,
                 rng.randrange(1 << WIDTH), rng.randrange(1 << WIDTH),
                 rng.randrange(2))


def _likely_overflow(rng, index):
    # Both operands drawn from the top half of the range, so addition
    # overflows far more often than chance would give it.
    a = rng.randrange(1 << (WIDTH - 1), 1 << WIDTH)
    b = rng.randrange(1 << (WIDTH - 1), 1 << WIDTH)
    return _case("likely overflow #%d" % index, a, b, rng.randrange(2),
                 "Both operands drawn large, so this one overflows more often than not.")
